const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

function quotePremium(items: Item[]): number {
  const policyBase = items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
  const total = policyBase + policyBase * FIRST_INSURANCE_SURCHARGE;
  return Math.ceil(total + PROCESSING_FEE);
}

export function runScenario(scenario: Scenario): ScenarioOutput {
  return {
    results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })),
  };
}

