const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
const BLOCK_SIZE = 3;
const BLOCK_PREMIUM = 60;

/**
 * Components of one type are priced in blocks: each complete group of
 * BLOCK_SIZE alike components costs BLOCK_PREMIUM, the remainder is priced
 * per unit.
 */
function componentBase(type: string, count: number): number {
  const blocks = Math.floor(count / BLOCK_SIZE);
  const loose = count % BLOCK_SIZE;
  return blocks * BLOCK_PREMIUM + loose * BASE_PREMIUMS[type];
}

function policyBasePremium(items: Item[]): number {
  const componentCounts = new Map<string, number>();
  let base = 0;

  for (const item of items) {
    if (COMPONENT_TYPES.has(item.type)) {
      componentCounts.set(item.type, (componentCounts.get(item.type) ?? 0) + 1);
    } else {
      base += BASE_PREMIUMS[item.type];
    }
  }

  for (const [type, count] of componentCounts) {
    base += componentBase(type, count);
  }

  return base;
}

function quotePremium(items: Item[]): number {
  const policyBase = policyBasePremium(items);
  const total = policyBase + policyBase * FIRST_INSURANCE_SURCHARGE;
  return Math.ceil(total + PROCESSING_FEE);
}

